  protected readonly dueTotal = computed(() =>
    money(
      this.people().reduce((sum, p) => {
        const pct = this.pctOf(p.grade);
        return pct === null ? sum : sum + dueCents(this.claimedCents(p.id), pct);
      }, 0),
    ),
  );
